/**
 * 云端「条目商店」· 前端（P3 骨架，接本地假后端）
 *   依据：《预设更新器-云端商店-定稿方案》§4.1/§4.3 数据格式、§4.4 接口表、§4.5 字段校验、
 *        §7 前端结构与入口（★主入口 = 工具箱卡片列表**最前**，第二入口 = 更新器窗口第三个标签）、
 *        §1 不变量（不静默改预设 / 不覆盖同名 / 离线静默 + console.warn / **陌生人文本一律 esc()**）、
 *        §17（交互 v2：手风琴预览 / BY 署名 / 右下角缝入 / 向导勾选 + 弹窗 / 版权提醒）
 *
 * 独立数据源：**完全不用 S.analysis**（没点过"开始对比"也能逛/能传）——
 *   自己用 listPresetNames() + 内核 indexPreset() 列条目。
 *
 * 依赖：preset-merge.js（内核：indexPreset / resolveAnchor / diffBlocks / assembleFromBlocks / clonePreset / getOrderGroup）
 * ★P7（2026-09-20 · 定稿方案 §15）：**"缝"这个动作已经全部交给更新器** ——
 *   商店只负责"挑包 + 挑缝进哪一份"（点卡 = **就地展开** → 「缝入当前预设」）；拼接/对比/逐条挑/写盘都在
 *   `preset-updater.js` 的 `openStorePack()` 里（复用更新器那套完整对比页 + 另存新名，绝不覆盖同名）。
 * ★§17（2026-09-20 第二轮）：**点卡片不再跳"预览页"** ——
 *   · 点卡片本体 = **卡片下方就地展开**（手风琴：同时只开一张，再点收起）；卡片右上/右下才是动作区
 *   · 展开里每条条目一行、行尾一个折角，**点整行** = 摊开"这条跟你手上那份的初步对比"（只读红/蓝）
 *   · 卡片右下角「缝入当前预设」= 唯一动作（= 老的"到更新器里挑"，只换了位置/措辞/样式）
 * 与 preset-store.css 一起**不进仓库**（跟更新器三件套同样走发布隔离；index.js 里 import 成功才建卡片）。
 */
