const $ = (sel, root) => (root || document).querySelector(sel);
const $$ = (sel, root) => [...(root || document).querySelectorAll(sel)];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const clip = (s, n) => { const t = String(s ?? ''); return t.length > n ? t.slice(0, n) + ' …' : t; };
/** ★G32（作者台账）：上传页里用户能填的文字（标题 / **用途说明** / 条目正文预览）**支持 Markdown 渲染**。
 *  ★**自己写**（硬约束：不许引外部库、不许用 marked/DOMPurify —— 那两个都会被 ST 的 CSP/离线约束卡住）。
 *  支持的语法就够用：**粗体** / *斜体* / `行内代码` / 换行 / 无序列表 / 有序列表 / [链接](http://x)。
 *  ★**渲染前必须转义**（铁律 §1.7：陌生人文本一律 esc）——所以顺序是：
 *     ① 整串先 `esc()`（把 `<img onerror>` 变成 `&lt;img …&gt;`）→ ② 再在**转义后**的串上做行内替换，
 *        替换产出的是**我们自己的** `<strong>/<code>/<a>` 标签（用户输入里的 `<` 早变成 `&lt;` 了，拼不出标签）。
 *     ③ 链接只放行 `http/https` 且加 `rel="noreferrer noopener"` + `target="_blank"`；**图片语法（`![]()`）
 *        不渲染成 `<img>`**（外链图片 = 加载远程资源 + 追踪像素，直接按字面显示）。
 *        ★★AA-1⑤（作者第六批反馈）：作者原话"上传第二步用途说明里的链接**要能点**（Markdown 链接 + **裸地址**
 *        都要可点，注意转义）"。改前只有 `[文字](地址)` 会变 `<a>`，直接写 `http://…` 的**裸地址是死字**。
 *        现在裸地址也变 `<a>`；做法用**占位符**（先把 Markdown 链接抽出来换成 `\u0000n\u0000`，裸地址替换只在
 *        **没被抽走的那几段**上做，最后还原）—— 不然会把 `<a href="…">` 里的地址**再包一层**（嵌套 a，
 *        点一下会开出两个标签页）。顺序仍然是"先 esc 再拼我们自己的标签"（用户输入里的 `<` 早变成 `&lt;` 了，
 *        拼不出标签，XSS 铁律没松）。
 *     ④ 列表行成组包 `<ul>/<ol>`；空行分段。返回的是**已经转义过的 HTML**，调用方直接 innerHTML 即可。 */
function mdRender(src) {
    const raw = esc(String(src ?? ''));
    if (!raw) return '';
    /* ★AA-1⑤：链接标签只有一个构造器 —— Markdown 链接与裸地址**属性顺序/rel/target 一处定义**，
       将来要加 `title` 或收口协议只改这一行。 */
    const linkOf = (url, txt) => '<a class="yws-link" href="' + url + '" target="_blank" rel="noreferrer noopener">' + (txt || url) + '</a>';
    const inline = (t) => {
        /* ① 图片语法 `![alt](url)` **不**渲染成 img —— 按字面显示成「（图片：alt）」。
           必须在链接抽取**之前**做：否则它括号里那个地址会先被裸地址规则变成 <a>，这条规则就匹配不到了。 */
        let s = t.replace(/(^|[^`])!\[([^\]\n]*)\]\((https?:\/\/[^\s)]+)\)/g, (m, pre, alt) => pre + '（图片：' + alt + '）');
        /* ② 把"不可再解释"的两样抽成占位符：Markdown 链接 + **行内代码**（占位符里没有 Markdown 符号、
              也没有 `http` 与 `<`，下面两步都碰不到它们。行内代码先抽 ⇒ 它里面的 `**` 与裸地址都不会被改写） */
        const keep = [];
        const stash = (html) => { keep.push(html); return '\u0000' + (keep.length - 1) + '\u0000'; };
        s = s.replace(/`([^`\n]+)`/g, (m, a) => stash('<code class="yws-code">' + a + '</code>'));
        s = s.replace(/(^|[^!])\[([^\]\n]*)\]\((https?:\/\/[^\s)]+)\)/g, (m, pre, txt, url) => pre + stash(linkOf(url, txt)));
        /* ③ 粗体 / 斜体 / **删除线**（只在**非链接、非代码**的正文段上做）
           ★★U12（§BO-9）：`~~删除~~` 补上 —— 作者报的"写了 Markdown 没渲染"，改前渲染器里
             标题 / 引用 / 分隔线 / 删除线**四样都不认**（写了就原样显示成一串符号）。 */
        s = s.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
            .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>')
            .replace(/~~([^~\n]+)~~/g, '<del class="yws-mddel">$1</del>');
        /* ④ 裸地址 → `yws-link`（★AA-1⑤）。前面必须是行首/空白/开括号（别把 `xhttp://` 当链接）；
              结尾不许吃进 `<>"'` 与控制符；**收尾的句号/逗号/右括号还给正文**（"见 http://a.com。"别把句号吞了）。 */
        s = s.replace(/(^|[\s(（\[【])(https?:\/\/[^\s<>"'\u0000]+)/g, (m, pre, url) => {
            let tail = '';
            const tm = url.match(/[.,;:!?、。，；：！？)）\]】]+$/);
            if (tm) { tail = tm[0]; url = url.slice(0, url.length - tail.length); }
            return url ? pre + linkOf(url, url) + tail : m;
        });
        /* ⑤ 还原 */
        return s.replace(/\u0000(\d+)\u0000/g, (m, i) => keep[Number(i)] || '');
    };
    const out = [];
    let list = null;                                  // 'ul' | 'ol' | null
    const closeList = () => { if (list) { out.push('</' + list + '>'); list = null; } };
    for (const line of raw.split(/\r?\n/)) {
        /* ★★U12（§BO-9）：**标题 / 引用 / 分隔线**补上（顺序：分隔线 → 引用 → 标题 → 列表）——
           `---` 那一行如果交给列表规则会变成一条奇怪的 `li`，所以最先判它。
           ★注意这里已经走过 `esc()`（本函数第①步）⇒ 引用行那个 `>` 是 **`&gt;`**，判据要按它写
             （写在 `esc()` 之前的话，用户输入里的 `>` 会被当成语法、而正文里的 `>` 又漏判）。 */
        if (/^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)) { closeList(); out.push('<div class="yws-mdhr"></div>'); continue; }
        const qt = line.match(/^\s*(?:&gt;|>)\s?(.*)$/);
        if (qt) { closeList(); out.push('<div class="yws-mdq">' + inline(qt[1]) + '</div>'); continue; }
        const hd = line.match(/^\s*(#{1,6})\s+(.+?)\s*#*\s*$/);
        if (hd) { closeList(); out.push('<div class="yws-mdh yws-mdh' + hd[1].length + '">' + inline(hd[2]) + '</div>'); continue; }
        const ul = line.match(/^\s*[-*+]\s+(.+)$/);
        const ol = line.match(/^\s*\d+[.)]\s+(.+)$/);
        if (ul || ol) {
            const want = ul ? 'ul' : 'ol';
            if (list !== want) { closeList(); out.push('<' + want + ' class="yws-mdl">'); list = want; }
            out.push('<li>' + inline((ul || ol)[1]) + '</li>');
            continue;
        }
        closeList();
        out.push(line.trim() ? '<p class="yws-mdp">' + inline(line) + '</p>' : '<div class="yws-mdbr"></div>');
    }
    closeList();
    // 最后一行是空行时别留一个孤零零的分段（避免卡片/预览底部多一截空白）
    while (out.length && out[out.length - 1] === '<div class="yws-mdbr"></div>') out.pop();
    return out.join('');
}
/** Markdown 的**纯文本**版（给 title 属性 / 卡片上那句被截断的简写用：别把 `**` 原样甩给用户）
 *  ★★U12（§BO-9）：新认的那四样（标题 `#` / 引用 `>` / 分隔线 `---` / 删除线 `~~`）也在这里剥掉 ——
 *  卡片标题与 tooltip 上**不许**出现 `##` 这种符号（它们本来就只该显示成文字）。 */
const mdPlain = (s) => String(s ?? '').replace(/`([^`\n]+)`/g, '$1').replace(/\*\*([^*\n]+)\*\*/g, '$1')
