// ---------------------------------------------------------------- 酒馆预设读写

function presetManager() {
    try { const ctx = window.SillyTavern?.getContext?.(); return ctx?.getPresetManager ? ctx.getPresetManager(API_ID) : null; }
    catch (e) { warn('取预设管理器失败', e); return null; }
}
function listPresetNames() {
    try { const pm = presetManager(); return pm ? (pm.getAllPresets() || []) : []; } catch (e) { return []; }
}
