        /* ★★§BJ-E15/16：**手动刷新 / 进面板**也顺手问一遍"有没有人回我"（节流 60 秒，同一分钟内不重复问）。
           fire-and-forget：不拖慢这一发刷新，也不弹任何错（拉不到时那一页自己会写人话）。 */
        void repScan({});
        /* ★★W77（2026-09-27 夜 · 作者拍板「免审窗口」）：**进面板 / 手动刷新这一发里顺带问一次窗口状态**
           （fire-and-forget：不拖慢刷新、失败静默；**没填审核密钥时它第一句就返回** ⇒ 普通人零额外请求）。
           拿到之后 `loadAwin()` 自己会把卡片标题上那个「（N待审）」重算一遍。 */
        void loadAwin(true);
