        //   以前这里 `S.cards = []`，而 online 仍是 true（HTTP 4xx/5xx 不标离线）→ checkStitched 拿空列表判定
        //   → 顶部宣布"你缝过的条目全下架了"（Cloudflare 的 502/522/500 都走这条路，用户会以为自己缝的东西被人撤了）。
        //   现在：**保留上一份已知数据** + 标 `cardsStale`（界面如实写"这是上次的数据"）+ 只在成功拉到列表时才做"已下架"判定（★W21-C：界面词统一成「已下架」）。
        S.lastErr = (e && e.message) || String(e);
        S.lastErrStatus = Number((e && e.status) || 0);
