    const st = S.stats || {};
    const nums = bannerNums(st, S.cards, s);
    if (!nums.legacy) {
        const unread = Math.max(0, Number(nums.official) || 0) + Math.max(0, Number(nums.user) || 0);
        return { unread, version: S.version, legacy: false };
    }
    // ★服务端给的数字也要夹一道：脏数据不能顺着 innerHTML 变成 HTML（numOf 只对数字负责）
    const unread = Number(st.unread) || Math.max(0, S.version - (s.readVersion || 0));
