        // ★key 里必须有 **视图 + 元素个数**：换一页（商店 → 上传向导 → 我的）、或向导从第①步走到第②步，
        //   都会长出上一次没扫过的元素；只看主题的话它们永远轮不到（第一版就是这么漏的：
