    const s = (pg && pg.secs && pg.secs[w]) || null;
    if (!s) return '';
    const tag = w === 'official' ? '官方条目' : (w === 'play' ? '小剧场' : (w === 'wish' ? '许愿 / 交流' : '用户条目'));
    const pre = 'pg' + (w === 'official' ? 'o' : (w === 'play' ? 'p' : (w === 'wish' ? 'w' : 'u')));
