    const rep = (S.view === 'mine' && S.mySeg === 'rep');
    const sel = rep ? '.yws-replist > .yws-reprow' : '.yws-mylist > .yws-myrow';
    const barName = rep ? 'rep' : 'mine';
    const pre = rep ? 'rpg' : 'mpg';
    const tag = rep ? '回复我的' : '我的上传';
    const pg = rep ? repListPage() : myListPage();
