/** 删某一版：二次确认（纯文本，把影响面逐字说清）⇒ /base/unseed */
async function baseAdminDelete(ver) {
    const v = String(ver || '').trim();
    if (!v) return;
    const it = baseItems().find((x) => String(x.ver || '') === v) || {};
    /* ★★W19-B：确认话里点名的是**预设名**（库里那份 title）—— 版本号是内部键，不该出现在人话里（作者拍板）。 */
    const nm = String(it.title || '').trim() || v;
    const okDel = await askYes('把「' + nm + '」从基准库里摘掉？',
        '摘掉之后：<b>卡片和评论一个字节都不动</b>；<b>本机装着、或缓存过这份预设的人照旧认得出</b>；' +
        '只有"将来要新下这一版"的人会看到「库里没有那一版」（只能两方对比）。',
        '摘掉',
        '把「' + v + '」从基准库里摘掉？\n摘掉之后：卡片和评论一个字节都不动；本机装着、或缓存过这一版的人照旧认得出；' +
        '只有将来要新下这一版的人会看到"库里没有那一版"。');
    if (!okDel) { toast('info', '好，什么都没动。'); return; }
    try {
        const r = await api.baseUnseed(v);
        toast('success', (r && r.why) || ('已摘掉 ' + v));
        await loadBaseList(true); renderAll();
        if (typeof refresh === 'function') void refresh(true);
    } catch (e) {
        const st = Number(e && e.status);
        toast('error', st === 403 ? '这台后端不认你的审核密钥 ⇒ 管理不了基准库（密钥在插件设置里）' : ('没删成：' + ((e && e.message) || e)));
        warn('base/unseed 失败', e);
    }
}
