            '<span class="yws-banner-txt">' + esc(repBannerText(n)) + '</span>' +
            '<button class="yws-btn yws-primary yws-mini" data-act="rep-banner-go">去看看</button>' +
            '<button class="yws-btn yws-mini" data-act="rep-banner-later" title="先不看（下次打开商店还会提醒 —— 只有点了「已读」才真的不再提醒）">稍后</button>';
