        w.picked = pre.picked;
        /* ★★D2：「hid」= 老包里那几条**已经隐掉**的条目（= 在源预设里是 ST 隐藏的幽灵、列表里已经没有它们）
           ⇒ 这一次"编辑并更新"**不会再带出它们**（那正是他要的），但必须**如实说一句**（见 `hidLine`）。 */
