        if (!items.length || !src) return null;
        const preset = readPreset(src);                 // 本机那份（读不出就 null，见 catch）
        if (!preset || !Array.isArray(preset.prompts)) return null;
        const cands = items.map(it => ({ ver: String(it.ver), title: String(it.title || ''), fingerprint: it.fpFull }));
        const rk = PM.rankPresetCandidates(preset, cands, { minHitScore: 0.6 });
