/** ★C20③：**与官方旧版的对比** —— 逐条算"挑的这几条跟官方旧版哪里不一样"（新增 / 改写）。
 *  口径：按 identifier（退化成规范化名字）跟「官方旧版」那份配对；**跟旧版一字不差的条目不占地方**。
 *  没填官方旧版（或读不到那份）→ 返回**空数组**（调用方一个字都不渲染 → 不留空盒子）。纯只读。 */
