        const gone = (an.items || []).filter(it => it.mine && !it.next);
        for (const it of gone.slice(0, 6)) rows.push({
            key: 'd:' + (it.mine.name || ''), name: String(it.mine.name || '（未命名）'), tag: '删除', cls: 'yws-tag-old',
            stat: '这条在新那份里没有 → 缝完之后你手上的会被删掉', pairs: [], more: 0, body: '', kind: 'text',
        });
        if (gone.length > 6) rows.push({ key: 'd:more', name: '还有 ' + numOf(gone.length - 6) + ' 条会被删掉', tag: '', cls: '', stat: '', pairs: [], more: 0, body: '', kind: 'text' });
