        // ★★D2：第二个实参 = **顺序表里的真实开关**（e.enabled；幽灵进不来、这里不会是 null）——
        //   有了它，"关着"的条目传出去在对方那边**还是关着**（收侧 preset-updater.js 的 conv() 已改成跟随）。
        return { mode: 'new', entry: Object.assign({ name: e.name, content: e.text }, stFields(e.prompt, e.enabled)), place };
